  // i.e. `/admin/custom-view/:id` -> `/admin/custom-view/123`
  // `end: true` requires the entire current route to match the full path pattern
  const regex = pathToRegexp(viewPath, keys, {
    end: true,
    sensitive,
    strict,
  })

  const match = regex.exec(currentRoute)

  if (exact) {
    return Boolean(match)
  }

  // The root path `/` would otherwise match every route as a prefix, so in
  // non-exact mode it must only ever match itself.
  if (viewPath === '/') {
    return Boolean(match)
  }

  // `end: false` matches the view path as a prefix, but only at a segment
  // boundary - i.e. `/dashboard` matches `/dashboard/settings` but not
  // `/dashboard-extra`.
  const prefixRegex = pathToRegexp(viewPath, [], {
    end: false,
    sensitive,
    strict,
  })

  const prefixMatch = prefixRegex.exec(currentRoute)

  if (!prefixMatch) {
    return false
  }

  // The prefix regex ignores a trailing slash, so when `strict` is set we must
  // reject a match that only differs from the view path by a trailing slash.
  if (strict) {
    const remainder = currentRoute.slice(prefixMatch[0].length)

    if (remainder === '/') {
      return false
    }
  }

  return true
