  AdminViewServerProps,
  PayloadComponent,
  SanitizedCollectionConfig,
} from 'payload'

import { isPathMatchingRoute } from './isPathMatchingRoute.js'

/**
 * Built-in collection view keys that are handled by dedicated routes and must
 * never be treated as custom views.
 */
const builtInViewKeys = ['edit', 'list']

export const getCustomCollectionViewByRoute = ({
  adminRoute,
  baseRoute,
  currentRoute: currentRouteWithAdmin,
  views,
}: {
  adminRoute: string
  baseRoute: string
  currentRoute: string
  views: SanitizedCollectionConfig['admin']['components']['views'] | undefined
}): {
  view: { payloadComponent?: PayloadComponent<AdminViewServerProps> }
  viewKey: string | null
} => {
  let viewKey: null | string = null

  const currentRoute =
    adminRoute === '/' ? currentRouteWithAdmin : currentRouteWithAdmin.replace(adminRoute, '')

  const foundView =
    (views &&
      typeof views === 'object' &&
      Object.entries(views).find(([key, view]) => {
        if (builtInViewKeys.includes(key)) {
          return false
        }

        if (!view || typeof view.path !== 'string' || !view.Component) {
          return false
        }

        const isMatching = isPathMatchingRoute({
          currentRoute,
          exact: view.exact,
          path: `${baseRoute}${view.path}`,
          sensitive: view.sensitive,
          strict: view.strict,
        })

        if (isMatching) {
          viewKey = key
        }

        return isMatching
      })?.[1]) ||
    undefined

  if (!foundView) {
    return {
      view: {},
      viewKey: null,
    }
  }

  return {
    view: {
      payloadComponent: foundView.Component as PayloadComponent<AdminViewServerProps>,
    },
    viewKey,
  }
}
